-- נוצר אוטומטית מ-lib/demo/buildings.ts (מקור אחד לנתוני הגיבוי ולמאגר)
-- מצגת הוועדה לשימור אתרים 2016 (ישיבה 201601): תיקונים ל-14 האתרים הקיימים ו-11 אתרים ממוספרים חדשים
-- גיבוי לפני השינוי: shimur_buildings_backup_20261012
INSERT INTO shimur_buildings (site_no, city_registry_id, name, address, neighborhood, parcel, is_complex, lat, lng, year_built, year_built_verified, architect, architect_verified, style, historical_periods, protection_level, documentation_reason, owner, current_use, building_type, preservation_reasons, priority_level, full_description, additional_info, iaa_reference, gov_sources, committee_no, list_status, statutory_ref, coords_approx, data_conflict, components, risk_note, grade_note) VALUES
(1, 'ASH-001', 'המגדלור בגבעת יונה', 'גבעת יונה, רובע א׳', 'רובע א׳', '2077/2', false, 31.81391, 34.64633, NULL, false, NULL, false, 'מגדל ניווט', ARRAY['תקופה ישראלית']::text[], 'א', 'היסטורית, אדריכלית', 'ממ"י / עיריית אשדוד', 'קיים - סגור למבקרים, השימוש הופסק', 'מגדל ניווט', ARRAY['היסטורית','אדריכלית','ארכאולוגית']::text[], 'גבוהה', 'מגדלור נמל אשדוד. גובה המגדל כ-42 מ׳, ומוקד האור נמצא כ-76 מ׳ מעל פני הים. אות ניווט של שלושה הבזקים כל 20 שניות, שנראו למרחק של כ-25 מייל. החלק התחתון של המבנה משולש והעליון עגול. סגור כיום למבקרים.', 'נמצא בגבעת יונה — הגבעה הגבוהה ביותר באשדוד (53 מ׳ מעל פני הים). נבנה באמצע שנות ה-60 עם הקמת נמל אשדוד, העדשה הועברה ממגדלור יפו שהושבת באותה תקופה. לפי מצגת הוועדה: השימוש במגדלור הופסק בעשור הראשון של המאה ה-21, והוא הונצח בבול ב-2009. בגבעה שרידים מתקופות הברונזה, הברזל והפרסית (2000–332 לפנה״ס).', NULL, '{}'::text[], '1', 'committee_2016', NULL, false, 'גובה: לפי המקורות שנבדקו (ויקיפדיה, Ashdod Light) מוקד האור כ-76 מ׳ מעל פני הים, ובמצגת הוועדה 138 מ׳ מעל פני הים.', ARRAY['המגדלור','גבעת יונה – אתר ארכאולוגי']::text[], NULL, NULL),
(2, 'ASH-002', 'גשר עד הלום / הפילבוקס / עמדת ויקרס', 'פארק עד הלום', 'נחל לכיש', '182/49-51', false, 31.78206, 34.6694, NULL, false, NULL, false, 'גשר היסטורי', ARRAY['תקופה ממלוכית','תקופה מנדטורית','תקופה ישראלית']::text[], 'א', 'לאומית, היסטורית', 'ממ"י / עיריית אשדוד', 'קיים - פארק עד הלום', 'גשר היסטורי', ARRAY['לאומית','היסטורית']::text[], 'גבוהה', 'גשר אבן ממלוכי מהמאה ה-13 בעל שלוש קשתות, החוצה את נחל לכיש. פוצץ ב"ליל הגשרים" ב-1946, ושוב ב-12.5.1948 על ידי לוחמי גבעתי כדי לעצור את ההתקדמות המצרית — "עד הלום". במקום מצדית בטון (פילבוקס) ששימשה את לוחמי גבעתי ב-1948, ועמדת ויקרס.', 'אתר הנצחה לאומי. כאן נעצרה ההתקדמות המצרית במלחמת העצמאות. הגשר הוכרז כאתר מורשת. הפארק מנוהל על ידי עיריית אשדוד. לפי מצגת הוועדה: הגשר עומד על שלוש אומנות. בליל 15.5.48 פוצצה מחלקה מגדוד 51 של גבעתי אחת האומנות. ההתקפה ב-7–8.6.48 נכשלה, והאזור נכבש ב-27.10.48, לאחר נסיגת המצרים בעקבות מבצע "יואב". הפילבוקס: מצדית בטון מימי המנדט (1936). עמדת ויקרס: נוצקה בידי חיילים מצרים במאי 1948.', NULL, ARRAY['https://en.wikipedia.org/wiki/Ad_Halom']::text[], '2', 'committee_2016', NULL, false, 'תיארוך הגשר: לפי ויקיפדיה (Jisr Isdud) גשר ממלוכי מהמאה ה-13, ולפי מצגת הוועדה נבנה בשלהי המאה ה-19 בידי הטורקים על יסודות גשר רומי. תאריך הפיצוץ ב-1948: 12.5 לעומת 15.5 במצגת.', ARRAY['גשר עד הלום','הפילבוקס','עמדת ויקרס']::text[], NULL, NULL),
(3, 'ASH-003', 'אובליסק מצרי', 'פארק עד הלום', 'נחל לכיש', '182/33', false, 31.78191, 34.66647, 1990, false, NULL, false, 'אנדרטה', ARRAY['תקופה ישראלית']::text[], 'ב', 'לאומית, היסטורית', 'עיריית אשדוד / קבע', 'קיים', 'אנדרטה', ARRAY['לאומית','היסטורית']::text[], 'בינונית', 'אנדרטה לזכר החללים המצרים בגזרת אשדוד (איסדוד) במלחמת העצמאות. הוקמה ב-1990, אחרי הסכם השלום עם מצרים (1979). כתובות בערבית, באנגלית, בעברית ובכתב הירוגליפי.', 'הוקמה במסגרת ההסכמות שבין ישראל למצרים, בתמורה לשמירת אנדרטאות ישראליות בסיני. ביטוי חריג לפיוס בנוף הזיכרון הישראלי.', NULL, '{}'::text[], '3', 'committee_2016', NULL, false, 'שנת הקמה: 1990 לפי מצגת הוועדה, 1989 בגרסה קודמת של הרשומה.', '{}'::text[], NULL, NULL),
(4, 'ASH-004', 'הקליפורניות (בנק הפועלים + בנק לאומי)', 'רח׳ הורדים 7 ו-3', 'רובע א׳', '2061/161', false, 31.8084, 34.6465, NULL, false, NULL, false, 'בנק / מסחר', ARRAY['תקופה ישראלית']::text[], 'ב', 'היסטורית', 'רמ"י', 'קיים', 'בנק / מסחר', ARRAY['היסטורית']::text[], 'בינונית', 'מבני הבנקים הראשונים ברובע א׳ — בנק הפועלים ובנק לאומי — משנות ה-60. מבנים חד-קומתיים המייצגים את ראשית הפעילות הכלכלית בעיר הצעירה.', 'מהמבנים הציבוריים הראשונים באשדוד, עדות לפעילות הבנקאית שהחלה עם הקמת הנמל. דוגמה לאדריכלות המודרנית הישראלית של שנות ה-60. מקור הכינוי "הקליפורניות" — לאימות. לפי מצגת הוועדה: הורדים 7 — בנק הפועלים הראשון, הורדים 3 א׳ — בנק לאומי הראשון. מבנים בני קומה אחת מראשית שנות ה-60.', NULL, '{}'::text[], '10', 'committee_2016', NULL, false, NULL, '{}'::text[], NULL, NULL),
(5, 'ASH-005', 'בית קנדה — מרכז קליטה', 'שבי ציון 1', 'רובע א׳', '2061/111', false, 31.80873, 34.64458, NULL, false, 'משה לופנפלד', true, 'מרכז קליטה', ARRAY['תקופה ישראלית']::text[], 'א', 'אדריכלית, היסטורית', 'הסוכנות היהודית', 'פעיל - שופץ', 'מרכז קליטה', ARRAY['אדריכלית','היסטורית']::text[], 'גבוהה', 'מרכז קליטה שתכנן אדר׳ משה לופנפלד בתחילת שנות ה-60. מלבן עם שתי חצרות פנימיות, דירות של כ-15 מ"ר, בטון חשוף ברצועות אופקיות ועבודת קרמיקה צבעונית ליד הכניסה. הוקם בסיוע תרומה מקנדה. בשיפוץ (הסוכנות היהודית והפדרציות של צפון אמריקה) חופה הבטון באריחי גרניט, החלטה שנויה במחלוקת, ומעל החצרות נוספה תקרת זכוכית. עדיין פעיל.', 'אחד ממרכזי הקליטה הראשונים באשדוד, עדות לגלי העלייה של שנות ה-60.', NULL, '{}'::text[], '14', 'committee_2016', NULL, false, NULL, '{}'::text[], NULL, NULL),
(6, 'ASH-006', 'בית הכנסת הקראי — ענן הנשיא', 'רח׳ האצל 7', 'רובע א׳', '2061/64', false, 31.8106, 34.6449, NULL, false, NULL, false, 'בית כנסת', ARRAY['תקופה ישראלית']::text[], 'א', 'היסטורית, תרבותית', 'עיריית אשדוד', 'קיים - פעיל', 'בית כנסת', ARRAY['היסטורית','תרבותית']::text[], 'גבוהה', 'בית הכנסת של הקהילה הקראית באשדוד — הקהילה הקראית הגדולה בישראל. נקרא על שם ענן בן דוד (המאה ה-8), הנחשב למייסד הזרם הקראי.', 'הקראים הם זרם יהודי שאינו מקבל את סמכות התורה שבעל פה. רוב הקראים בישראל עלו ממצרים בשנות ה-50. המרכז הרוחני והמנהלי של הקהילה נמצא ברמלה, ובאשדוד מתגוררת הקהילה הגדולה ביותר.', NULL, ARRAY['https://www.heritage-center.org.il/']::text[], '17', 'committee_2016', NULL, false, NULL, '{}'::text[], NULL, NULL),
(7, 'ASH-007', 'מרכז רובעי א׳', 'שבי ציון 4 — המרכז המסחרי', 'רובע א׳', '2077/129-157 (ללא 139, 148)', false, 31.80798, 34.64525, NULL, false, NULL, false, 'מרכז מסחרי', ARRAY['תקופה ישראלית']::text[], 'א', 'אדריכלית, היסטורית', 'פרטיים', 'קיים', 'מרכז מסחרי', ARRAY['אדריכלית','היסטורית']::text[], 'גבוהה', 'הלב של רובע א׳ — שכונת האם של אשדוד. משמר את עקרון התכנון המקורי: קומת קרקע מסחרית עם קולונדה, משרדים בקומות שמעל על עמודים, ובריכת מים ציבורית. תוכנן בהשראת עקרונות התכנון המודרני (CIAM) של שנות ה-50 וה-60.', 'רובע א׳ נוסד בשנות ה-50 כשכונת אם של אשדוד. המרכז הרובעי תוכנן לשמש קהילה שלמה. הקולונדה והעמודים מאפיינים את האדריכלות הציבורית הישראלית של אותה תקופה. לפי מצגת הוועדה: במרכז פעלה התחנה המרכזית הראשונה של העיר (רחוב שבי ציון). קולנוע "דגון" נשרף ונבנה מחדש כמסחר בקומה אחת.', NULL, '{}'::text[], '15', 'committee_2016', NULL, false, NULL, '{}'::text[], NULL, NULL),
(8, 'ASH-008', 'הגן האדום', 'רח׳ חיבת ציון 8', 'רובע א׳', '2077/161', false, 31.8102, 34.6463, NULL, false, NULL, false, 'גן ילדים', ARRAY['תקופה ישראלית']::text[], 'ב', 'היסטורית', 'עיריית אשדוד', 'קיים', 'גן ילדים', ARRAY['היסטורית']::text[], 'בינונית', 'מגני הילדים הראשונים באשדוד, משנות ה-60, הצבוע אדום — הצבע שהקנה לו את שמו. מסמל את ראשית חיי הקהילה בעיר הצעירה. שמות הצוות הראשון — לאימות מול מקור עירוני.', 'מהמוסדות הציבוריים הראשונים שנפתחו ברובע א׳. צבעו האדום הבולט הפך לסמל עבור הדור הראשון של ילדי אשדוד. שימש גן ילדים פעיל עד לשנים האחרונות.', NULL, '{}'::text[], '11', 'committee_2016', NULL, false, NULL, '{}'::text[], NULL, NULL),
(9, 'ASH-009', 'לשכת עבודה', 'רח׳ הראשונים 7', 'רובע א׳', '2086/78', false, 31.81, 34.6475, NULL, false, NULL, false, 'משרד ציבורי', ARRAY['תקופה ישראלית']::text[], 'ב', 'היסטורית', 'רמ"י, בחכירה לפרטיים', 'משרד פרטי', 'משרד ציבורי', ARRAY['היסטורית']::text[], 'בינונית', 'מבנה משנות ה-60 ששימש כלשכת עבודה. עדות לפעילות ההסתדרות ומשרד העבודה בעיר הצעירה. בשנת 1966, בתקופת המיתון, היה מוקד לגל הפיטורים בעיר. כיום משמש כמשרד פרטי.', '1966 — שנת מיתון חמורה באשדוד, עם פיטורים והפגנות. עדות לעיר של פועלים ונמל.', NULL, '{}'::text[], '12', 'committee_2016', NULL, false, NULL, '{}'::text[], NULL, NULL),
(10, 'ASH-010', 'בית מלון ראשון', 'רח׳ הראשונים 43', 'רובע א׳', '2085/22', false, 31.8049, 34.6446, NULL, false, NULL, false, 'בית מלון', ARRAY['תקופה ישראלית']::text[], 'ב', 'היסטורית', 'פרטיים', 'קיים', 'בית מלון', ARRAY['היסטורית']::text[], 'בינונית', 'מבנה "שיכון" בן 3 קומות משנות ה-60, שעל פי המסורת המקומית שימש כבית המלון הראשון בעיר, ולאחר מכן כמשרד קצין העיר. עדות לצמיחה המהירה של העיר.', 'שימש מבקרים ופקידים בתקופת הקמת הנמל.', NULL, '{}'::text[], '18', 'committee_2016', NULL, false, NULL, '{}'::text[], NULL, NULL),
(11, 'ASH-011', 'פארק נחל לכיש', 'נחל לכיש', 'נחל לכיש', NULL, false, 31.8166, 34.6494, 1996, true, NULL, false, 'פארק', ARRAY['תקופה ישראלית']::text[], 'א', 'נופית, אקולוגית', 'רמ"י / חנ"י / עיריית אשדוד', 'קיים - פתוח לציבור', 'פארק', ARRAY['נופית','אקולוגית']::text[], 'גבוהה', 'פארק של כ-650 דונם שהוקם בשנת 1996 על ידי קק"ל לאורך הגדה הדרומית של נחל לכיש. שבילי הליכה ואופניים ופינת חי ובה, בין היתר, זברות ויענים. מסדרון אקולוגי חשוב לעיר.', 'הוקם במסגרת שיקום נחל לכיש. ריאה ירוקה לתושבי העיר.', NULL, ARRAY['https://visit.ashdod.muni.il/en/night-life/lachish-park/']::text[], NULL, 'texture', NULL, false, NULL, '{}'::text[], NULL, NULL),
(12, 'ASH-012', 'שדרת השקמים', 'פארק חולות אשדוד (מיקום משוער — לאימות)', 'נחל לכיש', NULL, false, 31.7744, 34.6607, NULL, false, NULL, false, 'גנון / שדרה', ARRAY['תקופה ישראלית']::text[], 'ב', 'אקולוגית, נופית', 'ממ"י / עיריית אשדוד', 'קיים', 'גנון / שדרה', ARRAY['אקולוגית','נופית']::text[], 'בינונית', 'שדרה של עצי שקמה (Ficus sycomorus) בדרום אשדוד. השקמה מוזכרת במקרא כעץ השפלה. השדרה מייצגת שכבה ביולוגית-נופית היסטורית של אזור אשדוד. לפי מצגת הוועדה: מקבץ עצי שקמה בקצה הצפון-מזרחי של פארק החולות, חלק משדרת השקמים הדרומית ועדות לדרך הים (ויה מאריס). גיל העצים — לאימות.', 'עץ השקמה (שקמה מקראית / Ficus sycomorus) הוא עץ מסורתי ארץ-ישראלי המוזכר במקרא. מהווה בית גידול לעופות ושמירה על מגוון ביולוגי.', NULL, '{}'::text[], NULL, 'texture', NULL, true, NULL, '{}'::text[], NULL, NULL),
(13, 'ASH-013', 'תל מור', 'קריית איתנים, צפון העיר — הגדה הצפונית של נחל לכיש', 'נחל לכיש', NULL, false, 31.8234, 34.65603, NULL, false, NULL, false, 'תל ארכאולוגי', ARRAY['תקופת הברונזה','תקופת הברזל','תקופה פרסית-הלניסטית']::text[], 'א', 'ארכאולוגית', 'קרקע ציבורית', 'קיים', 'תל ארכאולוגי', ARRAY['ארכאולוגית']::text[], 'גבוהה', 'תל ארכאולוגי בפי נחל לכיש, ממזרח לנמל אשדוד. 12 שכבות יישוב, מסוף תקופת הברונזה התיכונה ועד התקופה ההלניסטית. בברונזה המאוחרת — מבנים מבוצרים, ככל הנראה של חיל מצב מצרי, סמוך לעגינה בפי הנחל. מהתקופה ההלניסטית — מתחם צביעה.', 'נחפר בשנים 1959–1960 בידי משה דותן (מחלקת העתיקות), עם הקמת נמל אשדוד. דוח סופי: ט. ברקו (עורך), דוחות רשות העתיקות 32, 2007. לפי מצגת הוועדה: תקופות הברונזה, הברזל והפרסית (2000–332 לפנה״ס).', NULL, ARRAY['https://www.biblewalks.com/telmor/']::text[], NULL, 'archaeology', NULL, false, 'תקופות: מצגת הוועדה מסיימת בתקופה הפרסית (332 לפנה״ס), ודוח רשות העתיקות 32 מתעד גם שכבה הלניסטית.', '{}'::text[], NULL, NULL),
(14, 'ASH-014', 'מצודת אשדוד ים', 'חוף י״א — אשדוד ים', 'חוף הים', NULL, false, 31.7803, 34.6217, NULL, false, NULL, false, 'מצודה ארכאולוגית', ARRAY['תקופת הברזל','תקופה פרסית-הלניסטית','תקופה אסלאמית קדומה']::text[], 'א', 'ארכאולוגית, נופית', 'ממ"י', 'קיים - טיילת חוף', 'מצודה ארכאולוגית', ARRAY['ארכאולוגית','נופית']::text[], 'גבוהה', 'מבצר אומיי מסוף המאה ה-7 או המאה ה-8 (כ-60×40 מ׳), חלק משרשרת מבצרי חוף (רבאטאת). באתר הסמוך — ביצורי תקופת הברזל (המאה ה-8 לפנה"ס) ושרידים הלניסטיים. חפירות רשות העתיקות בשנים 1997–1999.', 'הוקמה לפני 1700, ולכן אינה "אתר לשימור" לפי התוספת הרביעית לחוק. בשל חשיבותה הוסדרה לשימור בתב"ע 122/101/02/3 ובתכנית האסטרטגית לטיילת החוף. הרבאט שימש מבצר דתי-צבאי לשמירה על החוף.', 'חפירות IAA 1997-1999', ARRAY['https://archaeological.wixsite.com/ashdodyam/copy-of-introducing-ashdod-yam']::text[], NULL, 'archaeology', 'תב"ע 122/101/02/3', false, NULL, '{}'::text[], NULL, NULL),
(15, 'ASH-015', 'חללי אגוז – אנדרטה', 'רובע ו׳', 'רובעים ותיקים', '2459/22', false, 31.792, 34.65, NULL, false, NULL, false, 'אנדרטה', ARRAY['תקופה ישראלית']::text[], 'א', 'לאומית', 'עיריית אשדוד', 'קיים', 'אנדרטה', ARRAY['לאומית']::text[], 'גבוהה', 'אנדרטה לזכר חללי אגוז ברובע ו׳. כלולה ברשימת הוועדה לשימור (2016), שהחליטה לכלול את כל האנדרטאות בעיר. פרטי ההקמה — לאימות.', NULL, NULL, '{}'::text[], '4', 'committee_2016', NULL, true, NULL, '{}'::text[], NULL, 'הצעה אוטומטית – לאישור הוועדה'),
(16, 'ASH-016', 'לזכר הבנים – אנדרטה', 'רחבת בית קנדה, רובע א׳', 'רובע א׳', '2088/79', false, 31.809, 34.6443, NULL, false, NULL, false, 'אנדרטה', ARRAY['תקופה ישראלית']::text[], 'א', 'לאומית, היסטורית', 'עיריית אשדוד', 'קיים', 'אנדרטה', ARRAY['לאומית','היסטורית']::text[], 'גבוהה', 'אנדרטה לזכר הבנים ברחבת בית קנדה, בלב רובע א׳. כלולה ברשימת הוועדה לשימור (2016), שהחליטה לכלול את כל האנדרטאות בעיר. פרטי ההקמה — לאימות.', NULL, NULL, '{}'::text[], '5', 'committee_2016', NULL, true, NULL, '{}'::text[], NULL, 'הצעה אוטומטית – לאישור הוועדה'),
(17, 'ASH-017', 'גן אלישבע ואנדרטת חיל הים', 'גן אלישבע, רובע א׳', 'רובע א׳', '2061/111', false, 31.8092, 34.6406, NULL, false, NULL, false, 'פארק ואנדרטה', ARRAY['תקופה ישראלית']::text[], 'א', 'לאומית, היסטורית', 'עיריית אשדוד', 'קיים', 'פארק ואנדרטה', ARRAY['לאומית','היסטורית']::text[], 'גבוהה', 'הפארק העירוני הראשון בעיר. הנטיעות ואבן הפינה ב-27.5.1960, על שם אלישבע אשכול. הגן נחנך ב-1967. בגן אנדרטת חיל הים.', NULL, NULL, '{}'::text[], '6', 'committee_2016', NULL, false, 'גוש/חלקה 2061/111 זהים לרשומת בית קנדה.', '{}'::text[], NULL, 'הצעה אוטומטית – לאישור הוועדה'),
(18, 'ASH-018', 'אנדרטת הנופלים לשחרור אשדוד', 'רובע ב׳', 'רובעים ותיקים', '2068/?', false, 31.806, 34.657, NULL, false, NULL, false, 'אנדרטה', ARRAY['תקופה ישראלית']::text[], 'א', 'לאומית', 'עיריית אשדוד', 'קיים', 'אנדרטה', ARRAY['לאומית']::text[], 'גבוהה', 'אנדרטה לזכר הנופלים בשחרור אשדוד. כלולה ברשימת הוועדה לשימור (2016), שהחליטה לכלול את כל האנדרטאות בעיר. פרטי ההקמה — לאימות.', NULL, NULL, '{}'::text[], '7', 'committee_2016', NULL, true, 'מיקום: בגרסת 2016 צוין גן בן-גוריון. מספר החלקה חסר במקור.', '{}'::text[], NULL, 'הצעה אוטומטית – לאישור הוועדה'),
(19, 'ASH-019', 'אנדרטת סטרומה ומפקורה', 'רח׳ רוגוזין / משה דיין', 'חוף הים', '2076/175', false, 31.8, 34.638, NULL, false, NULL, false, 'אנדרטה', ARRAY['תקופה ישראלית']::text[], 'א', 'לאומית, היסטורית', 'עיריית אשדוד', 'קיים', 'אנדרטה', ARRAY['לאומית','היסטורית']::text[], 'גבוהה', 'אנדרטה לזכר ספינות המעפילים סטרומה ומפקורה. כלולה ברשימת הוועדה לשימור (2016), שהחליטה לכלול את כל האנדרטאות בעיר. פרטי ההקמה — לאימות.', NULL, NULL, '{}'::text[], '8', 'committee_2016', NULL, true, 'אזור: ברשימת הוועדה "מרינה", בטבלה "רובע ד׳".', '{}'::text[], NULL, 'הצעה אוטומטית – לאישור הוועדה'),
(20, 'ASH-020', 'אנדרטה בסיטי', 'רח׳ הרצל, רובע הסיטי', 'רובעים ותיקים', '2072/37', false, 31.792, 34.64, NULL, false, NULL, false, 'אנדרטה', ARRAY['תקופה ישראלית']::text[], 'א', 'לאומית', 'עיריית אשדוד', 'קיים', 'אנדרטה', ARRAY['לאומית']::text[], 'גבוהה', 'אנדרטה ברחוב הרצל ברובע הסיטי. כלולה ברשימת הוועדה לשימור (2016), שהחליטה לכלול את כל האנדרטאות בעיר. פרטי ההקמה — לאימות.', NULL, NULL, '{}'::text[], '9', 'committee_2016', NULL, true, NULL, '{}'::text[], NULL, 'הצעה אוטומטית – לאישור הוועדה'),
(21, 'ASH-021', 'שיכון ארבע־משפחתי', 'רח׳ ההגנה 15 / רח׳ העשרים ואחד 6', 'רובע א׳', '2080/86', false, 31.8095, 34.6475, NULL, false, NULL, false, 'דיור', ARRAY['תקופה ישראלית']::text[], 'ב', 'היסטורית', 'פרטיים', 'קיים', 'דיור', ARRAY['היסטורית']::text[], 'בינונית', 'מבנה אותנטי בן שתי קומות, מהשיכונים הראשונים בעיר, מראשית שנות ה-60.', NULL, NULL, '{}'::text[], '13', 'committee_2016', NULL, true, NULL, '{}'::text[], NULL, 'הצעה אוטומטית – לאישור הוועדה'),
(22, 'ASH-022', 'בריכת המים ומבנה העירייה הראשון', 'מרכז רובע א׳', 'רובע א׳', '2077/138', false, 31.8077, 34.6455, NULL, false, NULL, false, 'מוסד ציבורי', ARRAY['תקופה ישראלית']::text[], 'ב', 'היסטורית, אדריכלית', 'פרטיים', 'קיים', 'מוסד ציבורי', ARRAY['היסטורית','אדריכלית']::text[], 'בינונית', 'בלב המרכז הרובעי. משרדי העירייה הראשונים בארבע קומות, חזיתות במסגרת קורות ועמודים מבטון חשוף, ועמודים "דמויי רגליים": בסיס רחב שהולך וצר כלפי מעלה. לצד המבנה בריכת המים הציבורית.', NULL, NULL, '{}'::text[], '16', 'committee_2016', NULL, true, NULL, '{}'::text[], NULL, 'הצעה אוטומטית – לאישור הוועדה'),
(23, 'ASH-023', 'שוק רובע ב׳', 'רובע ב׳', 'רובעים ותיקים', NULL, false, 31.8055, 34.658, NULL, false, NULL, false, 'שוק', ARRAY['תקופה ישראלית']::text[], 'א', 'לאימות', 'לאימות', 'קיים', 'שוק', '{}'::text[], 'גבוהה', 'השוק של רובע ב׳. ייבחן במסגרת תכנית ההתחדשות של הרובע.', NULL, NULL, '{}'::text[], '19', 'committee_2016', NULL, true, NULL, '{}'::text[], 'ייבחן במסגרת תכנית ההתחדשות של הרובע.', 'הצעה אוטומטית – לאישור הוועדה'),
(24, 'ASH-024', 'עץ השקמה ברובע ו׳', 'רובע ו׳', 'רובעים ותיקים', NULL, false, 31.7925, 34.651, NULL, false, NULL, false, 'עץ לשימור', ARRAY['תקופה ישראלית']::text[], 'א', 'נופית', 'לאימות', 'קיים', 'עץ לשימור', ARRAY['נופית']::text[], 'גבוהה', 'עץ שקמה ברובע ו׳, אתר נפרד משדרת השקמים. ייבחן במסגרת תכנית ההתחדשות.', NULL, NULL, '{}'::text[], '20', 'committee_2016', NULL, true, NULL, '{}'::text[], 'ייבחן במסגרת תכנית ההתחדשות של הרובע.', 'הצעה אוטומטית – לאישור הוועדה'),
(25, 'ASH-025', 'מעגנות הנמל, תחנת הכוח אשכול ומפעל רוגוזין', 'חוף הים הצפוני, עורף הנמל', 'חוף הים', NULL, false, 31.8388, 34.6551, NULL, false, NULL, false, 'מתחם תעסוקה היסטורי', ARRAY['תקופה ישראלית']::text[], 'א', 'אדריכלית, לאומית', 'חנ"י / חברת החשמל / רמ"י', 'קיים', 'מתחם תעסוקה היסטורי', ARRAY['אדריכלית','לאומית']::text[], 'גבוהה', 'מתחם התעסוקה ההיסטורי של אשדוד, רשומה אחת כמו ברשימת הוועדה: שובר הגלים ומעגנות הנמל, תחנת הכוח אשכול ומפעל רוגוזין. מפעל רוגוזין: בית חרושת לטקסטיל וצמיגים מראשית אשדוד-ים, שנרכש בהמשך בידי חברת החשמל.', NULL, NULL, '{}'::text[], '21', 'committee_2016', NULL, true, NULL, ARRAY['נמל – שובר גלים ומעגנות','תחנת הכוח אשכול','מפעל רוגוזין']::text[], 'לפי פרסום מ-12.7.2020 מפעל רוגוזין נהרס והשטח נמסר למדינה. לאמת את המצב הקיים.', 'הצעה אוטומטית – לאישור הוועדה')
